#include <iostream>
using namespace std;

int main()
{
    int b7 = 0;
    int b6 = 0;
    int b5 = 0;
    int b4 = 0;
    int b3 = 0;
    int b2 = 0;
    int b1 = 0;
    int b0 = 0;

    cout << "비트 8개를 왼쪽부터 입력(0 또는 1): ";
    cin >> b7 >> b6 >> b5 >> b4 >> b3 >> b2 >> b1 >> b0;

    int high = b7 * 8 + b6 * 4 + b5 * 2 + b4 * 1;
    int low = b3 * 8 + b2 * 4 + b1 * 2 + b0 * 1;

    cout << "10진수: " << high * 16 + low << endl;
    cout << "16진수 상위 자리 값: " << high << endl;
    cout << "16진수 하위 자리 값: " << low << endl;
    return 0;
}
